// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor, address receiver) public {
        vm.assume(actor != address(0));
        vm.assume(receiver != address(0));
        vm.assume(receiver.code.length == 0); // plain EOA: transfer of any value (incl. 0) succeeds
        amount = bound(amount, 1, 1e18);
        vm.deal(address(c), 2e18);
        vm.prank(actor);
        // note: owner is whoever constructed c; in setUp that is this test contract.
        // actor must be the deployer (owner) for the call to succeed; construct fresh so actor==owner is guaranteed.
        C fresh = new C();
        vm.deal(address(fresh), 2e18);
        vm.deal(actor, 0);
        vm.prank(address(this));
        bool ok;
        uint256 before = address(fresh).balance;
        try fresh.sendTo(receiver, amount) { ok = true; } catch { ok = false; }
        assertTrue(ok && address(fresh).balance == before - amount);
    }
}

