// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        vm.deal(address(c), 1e36);
    }

    function testFuzz_property(uint256 amount, address receiver) public {
        // keep the domain wide but admissible: at least 1 wei, receiver is a plain EOA-like address
        amount = bound(amount, 1, 1e30);
        vm.assume(receiver != address(0));
        vm.assume(receiver.code.length == 0);
        vm.assume(uint160(receiver) > 9); // avoid precompiles

        uint256 before = receiver.balance;

        // setUp deployed c, so msg.sender in C's constructor was address(this) = owner
        vm.prank(address(this));
        c.sendTo(receiver, amount);

        // GENERAL RULE: a successful sendTo credits the receiver with exactly `amount` wei.
        assertTrue(receiver.balance - before == amount);
    }
}

