pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e18);
        vm.deal(address(c), amount);
        Rejector r = new Rejector();
        vm.prank(address(this));
        bool ok;
        try c.sendTo(address(r), amount) { ok = true; } catch { ok = false; }
        assertTrue(ok == false);
    }
}

contract Rejector {
    fallback() external payable { revert(); }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address receiver, uint amount) public {
        require(receiver != address(0));
        require(amount > 0);

        bool ok;
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // A transfer attempt must not succeed unless the caller is authorized.
        assert(!ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

